solution:
def min_climb_cost(cost: list[int]) -> int:
    two_below = one_below = 0            # best totals for the two positions under the next step
    for c in cost:
        two_below, one_below = one_below, c + min(two_below, one_below)
    return min(two_below, one_below)     # the top is one or two moves above these

perf.naive:
def min_climb_cost(cost: list[int]) -> int:
    def best(i):                         # cheapest total to stand on step i, re-solved on every call
        if i < 0:
            return 0
        return cost[i] + min(best(i - 1), best(i - 2))
    n = len(cost)
    return min(best(n - 1), best(n - 2))
